    overflow: visible;
    justify-content: center;
    color: var(--描边);
    font-size: calc(var(--mainFontSize) * 1.15);
}

#send_form .fa-solid,
#quick-reply-rocket-button {
    font-size: calc(var(--mainFontSize) * 1.5);
}

