.drawer-icon.fa-fw:hover {
    opacity: 1 !important;
    overflow: visible;
    background: 
        linear-gradient(135deg, 
            var(--主色调) 0%, 
            var(--描边) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    -webkit-transform: rotate(-15deg);
    transform: rotate(-15deg);
