    linear-gradient(to top, 
    rgba(0, 0, 0, 1) 0%, 
    rgba(0, 0, 0, 0.8) 80%, /* 🐑顶部模糊(修改括号内最后一个数字0-1,以及百分比) */
    rgba(0, 0, 0, 0) 100%);
